/* Shared mobile bottom navigation. The desktop menus remain unchanged. */
function mobileIcon(name){const paths={user:'M20 21v-2a7 7 0 0 0-14 0v2M17 7a5 5 0 1 1-10 0 5 5 0 0 1 10 0',more:'M5 12h.01M12 12h.01M19 12h.01',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8'};return paths[name]?`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]}"/></svg>`:icon(name)}
function mobileAdminMode(){return location.hash.startsWith('#admin')&&isAdminPreview()}
function mobileNavItems(){return mobileAdminMode()?[['#admin','home','الرئيسية'],['#admin/products','bag','المنتجات'],['#admin/orders','orders','الطلبات'],['#admin/media','image','الصور']]:[['#home','home','الرئيسية'],['#shop','bag','تسوقي'],['#cart','box','السلة'],['#favorites','heart','المفضلة']]}
function mobileActiveLink(){const hash=location.hash||'#home';if(mobileAdminMode()){return ['#admin','#admin/products','#admin/orders','#admin/media'].includes(hash)?hash:'more'}const page=hash.split('/')[0];if(['#shop','#product'].includes(page))return '#shop';if(['#cart','#checkout'].includes(page))return '#cart';if(['#account','#signin','#signup','#forgot-password','#reset-password'].includes(page))return 'more';if(page==='#favorites')return '#favorites';if(['#orders','#success','#admin','#admin-login'].includes(page))return 'more';return '#home'}
function renderMobileNav(){let nav=$('#mobile-nav');if(!nav){nav=document.createElement('nav');nav.id='mobile-nav';nav.className='mobile-bottom-nav';nav.setAttribute('aria-label','التنقل الرئيسي للموبايل');document.body.append(nav)}const active=mobileActiveLink();nav.innerHTML=mobileNavItems().map(([href,ico,title])=>`<a href="${href}" class="mobile-nav-item ${active===href?'is-active':''}" ${active===href?'aria-current="page"':''}><span class="mobile-nav-icon">${mobileIcon(ico)}${href==='#cart'?'<b id="mobile-cart-count" class="mobile-cart-count" hidden></b>':''}</span><span>${title}</span></a>`).join('')+`<button type="button" id="mobile-more-button" class="mobile-nav-item ${active==='more'?'is-active':''}" aria-haspopup="dialog" aria-expanded="false" aria-controls="mobile-more" onclick="openMobileMore()"><span class="mobile-nav-icon">${mobileIcon('more')}</span><span>المزيد</span></button>`;updateMobileCartCount()}
function updateMobileCartCount(){const badge=$('#mobile-cart-count');if(!badge)return;const count=cart.reduce((n,item)=>n+item.qty,0);badge.hidden=!count;badge.textContent=count>99?'99+':String(count);badge.setAttribute('aria-label',count+' قطع في السلة')}
function closeMobileMore(){const dialog=$('#mobile-more');if(dialog?.open)dialog.close();$('#mobile-more-button')?.setAttribute('aria-expanded','false')}
function openMobileMore(){let dialog=$('#mobile-more');if(!dialog){dialog=document.createElement('dialog');dialog.id='mobile-more';dialog.className='mobile-more-sheet';dialog.setAttribute('aria-labelledby','mobile-more-title');document.body.append(dialog);dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeMobileMore()}if(e.target.closest('a'))closeMobileMore()});dialog.addEventListener('close',()=>$('#mobile-more-button')?.setAttribute('aria-expanded','false'))}
const admin=mobileAdminMode();const links=admin?[['#admin/catalogue','box','التشكيلات'],['#admin/clients','user','العملاء والحسابات'],['#admin/settings','settings','الإعدادات'],['#home','arrow','زيارة المتجر']]:[[currentAccount()?'#account':'#signin','user','حسابي'],['#orders','orders','طلباتي'],['#admin','settings','إدارة المتجر']];dialog.innerHTML=`<div class="sheet-handle" aria-hidden="true"></div><div class="mobile-more-heading"><div><h2 id="mobile-more-title">المزيد</h2><p>${admin?'كل أدوات إدارة متجرك':'كل ما تحتاجينه في مكان واحد'}</p></div><button class="icon-button" aria-label="إغلاق المزيد" onclick="closeMobileMore()">${icon('close')}</button></div><div class="mobile-more-links">${links.map(([href,ico,title])=>`<a href="${href}">${mobileIcon(ico)}<span>${title}</span>${icon('arrow')}</a>`).join('')}</div>${!admin&&collections.length?`<h3 class="sheet-section-title">التشكيلات</h3><div class="mobile-collection-links">${collections.map(c=>`<a href="#shop/${c.id}">${esc(c.name)}</a>`).join('')}</div>`:''}${currentAccount()?'<button class="mobile-signout" onclick="closeMobileMore();signOutAccount()">تسجيل الخروج</button>':''}`;dialog.showModal();$('#mobile-more-button').setAttribute('aria-expanded','true')}
const beforeMobileRender=render;
render=function(scroll=true){beforeMobileRender(scroll);renderMobileNav()};
window.addEventListener('hashchange',closeMobileMore);
const mobileViewport=window.matchMedia('(max-width: 800px)');mobileViewport.addEventListener('change',e=>{if(!e.matches)closeMobileMore()});
new MutationObserver(updateMobileCartCount).observe($('#count'),{childList:true,characterData:true,subtree:true});
